def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    divider = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if divider is None:
        return out

    counts = {}
    for row in grid:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [v for v in counts if v != background]
    if not colors:
        return out
    obj_color = colors[0]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj_color]
    if not cells:
        return out

    min_col = min(c for r, c in cells)
    max_col = max(c for r, c in cells)
    line_col = max_col + 1 if min_col > divider else min_col - 1
    if 0 <= line_col < w:
        for r in range(h):
            out[r][line_col] = 8
    return out
